CREATE OR REPLACE VIEW view_attendance_exec AS select `t1`.`employeeId` AS `employeeId`,`t1`.`EmployeeName` AS `EmployeeName`,`t1`.`WorkDate` AS `WorkDate`,`t1`.`EarlyMinute` AS `EarlyMinute`,`t1`.`EarlyCount` AS `EarlyCount`,`t1`.`LateMinute` AS `LateMinute`,`t1`.`LateCount` AS `LateCount`,`t1`.`AbsenteeismDays` AS `AbsenteeismDays`,`t1`.`MisscardCount` AS `MisscardCount`,`t1`.`WorkDateOverTime` AS `WorkDateOverTime`,`t1`.`RestOverTime` AS `RestOverTime`,`t1`.`HolidayOverTime` AS `HolidayOverTime`,`t1`.`OverTimeHours` AS `OverTimeHours`,`t1`.`ActualityDays` AS `ActualityDays`,`t1`.`ChanJia` AS `ChanJia`,`t1`.`HunJia` AS `HunJia`,`t1`.`PeiChanJia` AS `PeiChanJia`,`t1`.`SangJia` AS `SangJia`,`t1`.`ShiJia` AS `ShiJia`,`t1`.`BingJia` AS `BingJia`,`t1`.`TiaoXiu` AS `TiaoXiu`,`t1`.`NianJia` AS `NianJia`,`t1`.`BuRuJia` AS `BuRuJia`,`t2`.`job_number` AS `jobNumber` from ((select `hr_0003`.`hrm_attendance_report_data`.`emp_id` AS `employeeId`,(select `hr_0003`.`hrm_employee`.`employee_name` from `hr_0003`.`hrm_employee` where (`hr_0003`.`hrm_employee`.`employee_id` = `hr_0003`.`hrm_attendance_report_data`.`emp_id`)) AS `EmployeeName`,`hr_0003`.`hrm_attendance_report_data`.`work_date` AS `WorkDate`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '早退时长') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `EarlyMinute`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '早退次数') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `EarlyCount`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '迟到时长') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `LateMinute`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '迟到次数') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `LateCount`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` in ('旷工天数','旷工迟到天数')) then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `AbsenteeismDays`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` in ('上班缺卡次数','下班缺卡次数')) then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `MisscardCount`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '工作日加班') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `WorkDateOverTime`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '休息日加班') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `RestOverTime`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '节假日加班') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `HolidayOverTime`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '加班-审批单统计') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `OverTimeHours`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '出勤天数') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `ActualityDays`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '产假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `ChanJia`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '婚假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `HunJia`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '陪产假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `PeiChanJia`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '丧假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `SangJia`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '事假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `ShiJia`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '病假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `BingJia`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '调休') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `TiaoXiu`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '年假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `NianJia`,sum((case when (`hr_0003`.`hrm_attendance_report_data`.`field_name` = '哺乳假') then `hr_0003`.`hrm_attendance_report_data`.`value` else 0 end)) AS `BuRuJia` from `hr_0003`.`hrm_attendance_report_data` group by `hr_0003`.`hrm_attendance_report_data`.`emp_id`) `t1` left join `hr_0003`.`hrm_employee` `t2` on((`t1`.`employeeId` = `t2`.`employee_id`)));
