CREATE OR REPLACE VIEW view_salary_fixing AS select `b`.`employee_name` AS `EmployeeName`,`a`.`employee_id` AS `EmployeeID`,`a`.`id` AS `id`,max((case when ((`a`.`name` = '基本工资') and (`a`.`is_pro` = 1)) then `a`.`value` end)) AS `jbgz1`,max((case when ((`a`.`name` = '岗位工资') and (`a`.`is_pro` = 1)) then `a`.`value` end)) AS `gwgz1`,max((case when ((`a`.`name` = '职务工资') and (`a`.`is_pro` = 1)) then `a`.`value` end)) AS `zwgz1`,max((case when ((`a`.`name` = '基本工资') and (`a`.`is_pro` = 0)) then `a`.`value` end)) AS `jbgz0`,max((case when ((`a`.`name` = '岗位工资') and (`a`.`is_pro` = 0)) then `a`.`value` end)) AS `gwgz0`,max((case when ((`a`.`name` = '职务工资') and (`a`.`is_pro` = 0)) then `a`.`value` end)) AS `zwgz0` from (`hr_0003`.`hrm_salary_archives_option` `a` left join `hr_0003`.`hrm_employee` `b` on((`a`.`employee_id` = `b`.`employee_id`))) where (`b`.`employee_name` is not null) group by `b`.`employee_name`,`a`.`employee_id`;
